const meta = $('Build Gemini Request').first().json;
const res = $input.first().json;
const base = { user_id: meta.user_id, message: meta.message };

const fail = (msg) => {
  const parsed = { status: 'error', intent: 'unknown', error_message: msg };
  return [{ json: { ...base, status: 'error', intent: 'unknown', error_message: msg, parsed_json: parsed } }];
};

if (res.error) {
  const m = typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error));
  return fail('Loi goi Gemini: ' + m);
}

try {
  const text = (res?.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
  if (!text) return fail('Gemini tra ve noi dung rong');
  const p = JSON.parse(text.replace(/```json|```/g, '').trim());

  // Chuẩn hóa status: Gemini v0.9 trả về 'success' -> đổi thành 'ok' để tương thích Main Orchestrator
  const rawStatus = p.status || 'error';
  const status = (rawStatus === 'success' || rawStatus === 'ok') ? 'ok' : rawStatus;

  const event = p.event || {};
  const today = meta.current_date || new Date().toISOString().slice(0, 10);
  const addDays = (ymd, n) => new Date(new Date(ymd + 'T00:00:00Z').getTime() + n * 86400000).toISOString().slice(0, 10);
  const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);

  // Đọc dữ liệu từ đối tượng event theo Data Contract v0.9
  const title = (event.title && String(event.title).trim()) || String(meta.message || '').slice(0, 100);
  const duration_minutes = Math.min(480, Math.max(15, Number.parseInt(event.duration_minutes, 10) || 60));
  const date_range_start = isDate(event.date_range_start) ? event.date_range_start : today;
  let date_range_end = isDate(event.date_range_end) ? event.date_range_end : addDays(today, 6);
  if (date_range_end < date_range_start) date_range_end = date_range_start;

  const PERIOD = ['morning', 'afternoon', 'evening', 'any'];
  const preferred_period = PERIOD.includes(event.preferred_period) ? event.preferred_period : 'any';

  // Chuẩn hóa intent để Main Orchestrator nhận diện luồng sắp xếp lịch
  let intent = p.intent || 'unknown';
  if (intent === 'find_suitable_time') {
    intent = 'create_event'; // Đưa về chung luồng tạo/tìm lịch trống với Main Orchestrator
  }

  const out = {
    status: ['ok', 'needs_clarification', 'unsupported', 'error'].includes(status) ? status : 'error',
    intent: intent,
    title,
    duration_minutes,
    date_range_start,
    date_range_end,
    preferred_period,
    is_outdoor: typeof event.is_outdoor === 'boolean' ? event.is_outdoor : null,
    avoid_rain: event.avoid_rain === true,
    location: event.location ? String(event.location) : null,
    clarification_question: p.clarification_question ? String(p.clarification_question) : null,
    parsed_json: p
  };

  return [{ json: { ...base, ...out } }];
} catch (e) {
  return fail('Khong parse duoc JSON tu Gemini: ' + e.message);
}

